            //
            aOrbiterG = ((aWandererH + RotL64(aIngress, 5U)) + 0x3890AB69613DC068ULL) + aOASaltC[(((511U - aIndex) + 134U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aCross, 60U)) + 0xA674E162BAC6693EULL) + aOASaltA[((aIndex + 25U)) & S_SALT1];
            aOrbiterC = ((aWandererD + RotL64(aPrevious, 19U)) + 0x7DA872DDB40A359CULL) + aOASaltG[(((511U - aIndex) + 420U)) & S_SALT1];
