            aOrbiterK = (((aWandererF + RotL64(aCross, 35U)) + RotL64(aCarry, 21U)) + 0x1D396113DCC67143ULL) + aOASaltD[(((511U - aIndex) + 136U)) & S_SALT1];
            aOrbiterJ = (((aWandererC + RotL64(aIngress, 29U)) + RotL64(aCarry, 3U)) + 0x1DF3A3D29A83D5FDULL) + aOASaltF[(((511U - aIndex) + 80U)) & S_SALT1];
            aOrbiterD = ((aWandererG + RotL64(aPrevious, 43U)) + RotL64(aCarry, 39U)) + 0x1D158B747404AC09ULL;
