            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0x7A8A168F4E8D0411ULL) + aOUSaltG[((aIndex + 47U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0xE6124EF78156DD18ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x05174C9072C11FDDULL), 23U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x37F278F3E1C264C9ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xA853E0AB76BC4D2AULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8170D982E45A4B09ULL), 41U);
            //
            aIngress = aOrbiterD ^ RotL64(aOrbiterI, 19U);
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterC, 47U));
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterK, 27U));
            aIngress = aIngress + RotL64(aOrbiterB, 56U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ (((RotL64(aPrevious, 47U) + aOrbiterK) + RotL64(aOrbiterD, 53U)) + aWUSaltA[((aIndex + 425U)) & S_SALT1]);
            aWandererC = aWandererC + ((((RotL64(aIngress, 11U) + RotL64(aOrbiterI, 41U)) + aOrbiterG) + RotL64(aCarry, 19U)) + aWUSaltF[((aIndex + 246U)) & S_SALT1]);
