            aScatter = (RotL64(aCarry, 39U) + RotL64(aIngress, 3U)) ^ (RotL64(aPrevious, 54U) ^ RotL64(aCross, 19U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = (((aWandererK + RotL64(aCross, 50U)) + RotL64(aCarry, 23U)) + 0x2CD8A21A9C3F6A05ULL) + aOASaltH[((aIndex + 255U)) & S_SALT1];
            aOrbiterF = (aWandererH + RotL64(aScatter, 3U)) + 0x22EFC882F44EAC4FULL;
            aOrbiterC = ((aWandererI + RotL64(aIngress, 57U)) + RotL64(aCarry, 3U)) + 0x716DC6CB53C3A2BFULL;
            aOrbiterJ = ((aWandererE + RotL64(aPrevious, 13U)) + 0x2CC1EFD190483C3CULL) + aOASaltE[(((511U - aIndex) + 366U)) & S_SALT1];
            aOrbiterI = (aWandererJ + RotL64(aScatter, 43U)) + 0x1F3C65DAE656EBDCULL;
            aOrbiterA = ((aWandererA + RotL64(aCross, 29U)) + 0xCCFED8E8B6C97EF2ULL) + aOASaltB[(((511U - aIndex) + 416U)) & S_SALT1];
            aOrbiterH = ((aWandererD + RotL64(aPrevious, 19U)) + RotL64(aCarry, 43U)) + 0x1A6FA372C448B4D8ULL;
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x9F35222E4C1C6E69ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xB0E35FC24A52D1DFULL;
            aOrbiterC = RotL64((aOrbiterC * 0xB954A4C0FA70936DULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0xC95253F81A7CA094ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0x070BEE6C4DF5BD72ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x180C30C2C4514CCDULL), 27U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0xCE534A60C3495DCEULL) + aOUSaltA[((aIndex + 143U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xB2E70C9C0DEC119FULL;
            aOrbiterF = RotL64((aOrbiterF * 0x481B50C5E6D86A1DULL), 3U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x46068B6D2118AC8AULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xE94EDB62A2ABD845ULL) ^ aOUSaltB[(((511U - aIndex) + 420U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x5B791531DB8E7123ULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xA3AD1A430E727D2DULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xAF678ABE4488BF12ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x04BFB1702FBD7501ULL), 53U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x3B893D6BA2A714ACULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x1978680E81EBD51CULL) ^ aOUSaltE[(((511U - aIndex) + 179U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x2BC9B7E82C0E5285ULL), 21U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0x20D4E27BB929E1C2ULL) + aOUSaltC[(((511U - aIndex) + 429U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0x838712F7DD3BF230ULL) ^ aOUSaltG[(((511U - aIndex) + 301U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x66A416A8F32E1E13ULL), 35U);
