            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 6U) + RotL64(aOrbiterJ, 35U)) + aOrbiterH) + aWUSaltA[((aIndex + 457U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aCross, 53U) + aOrbiterG) + RotL64(aOrbiterC, 21U)) + RotL64(aCarry, 51U));
