            //
            aIngress = (RotL64(aFuseLaneB[((aIndex + 18938U)) & S_BLOCK1], 36U) ^ RotL64(aWindLaneD[((aIndex + 23571U)) & S_BLOCK1], 23U));
            aIngress ^= (RotL64(aShadowLaneD[((aIndex + 16804U)) & S_BLOCK1], 57U) ^ RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 21748U)) & S_BLOCK1], 13U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 17732U)) & S_BLOCK1], 22U) ^ RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 16729U)) & S_BLOCK1], 11U));
            aCross ^= (RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 21895U)) & S_BLOCK1], 53U) ^ RotL64(aPlasmaLaneD[((S_BLOCK1 - aIndex + 20151U)) & S_BLOCK1], 41U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
