            aOrbiterH = (((aWandererJ + RotL64(aScatter, 37U)) + RotL64(aCarry, 41U)) + 0xCCA7B3C87ABAEEDFULL) + aOASaltH[(((511U - aIndex) + 322U)) & S_SALT1];
